        let checkpoint = final_ingress_file(&root.join(row["checkpoint_archive"].as_str().unwrap()), usize::try_from(row["checkpoint_length"].as_u64().unwrap()).unwrap(), row["checkpoint_sha256"].as_str().unwrap());
        let mut restored = physical.clone(); let mut last = restored.len();
        let inverse = row["inverse"].as_array().unwrap(); assert!(inverse.len() <= 512);
        for edit in inverse {
            let start = usize::try_from(edit["start_byte"].as_u64().unwrap()).unwrap();
            let after = edit["after"].as_str().unwrap();
            let end = start.checked_add(after.len()).expect("bounded final inverse endpoint");
            assert!(end <= last); assert_eq!(restored.get(start..end), Some(after));
            restored.replace_range(start..end, edit["before"].as_str().unwrap()); last = start;
        }
        assert_eq!(restored, checkpoint, "complete final to frozen787 inverse");
        if path == source {
            assert_eq!(row["expected_sha256"], expected, "exact original c874 expected namespace");
            assert!(current == physical || current == checkpoint || current == frozen["e24"].as_str().unwrap() || current == frozen["legacy"].as_str().unwrap() || current == old["before"].as_str().unwrap(), "foreign final ingress stage");
            let supplied = if current == physical { checkpoint.clone() } else { current.to_owned() };
            selected = Some((checkpoint, supplied));
        }
    }
    selected.expect("six literal final source owners only")
}
#[test]
fn final_ingress_six_physical_owners_preserve_frozen_stages_and_expected_dispatch() {
    let frozen = integrated_records(); let old = records();
    for ((row, old), (source, physical)) in frozen.as_array().unwrap().iter().zip(old.as_array().unwrap()).zip(CURRENT) {
        let expected = old["before_sha256"].as_str().unwrap();
        let (checkpoint, supplied) = final_ingress_checkpoint(source, expected, physical);
        assert_eq!(checkpoint, supplied); assert_eq!(digest(&checkpoint), row["current_sha256"]);
        for staged in [checkpoint.as_str(), row["e24"].as_str().unwrap(), row["legacy"].as_str().unwrap(), old["before"].as_str().unwrap()] {
            let (again, supplied) = final_ingress_checkpoint(source, expected, staged);
            assert_eq!(again, checkpoint); assert_eq!(supplied, staged);
            assert_eq!(acquire_expected(source, expected, staged), old["before"].as_str().unwrap());
        }
        assert_eq!(acquire_expected(source, &digest(physical), physical), physical);
        assert_eq!(acquire_expected(source, "older expected namespace", "older stage"), "older stage");
        for bad in [String::new(), format!("{physical} "), "foreign".to_owned()] {
            assert!(std::panic::catch_unwind(|| final_ingress_checkpoint(source, expected, &bad)).is_err());
        }
    }
